declare(strict_types=1);require_once __DIR__.'/../config/conexion.php';require_once __DIR__.'/../includes/seguridad.php';require_once __DIR__.'/../includes/permisos.php';require_role(['administrador','coordinador_mg']);requerir_permiso('mg.bitacora.ver');$tabla=trim($_GET['tabla']??'');$accion=trim($_GET['accion_filtro']??'');$desde=trim($_GET['desde']??'');$hasta=trim($_GET['hasta']??'');$w=[];$p=[];if($tabla){$w[]='b.tabla=?';$p[]=$tabla;}if($accion){$w[]='b.accion=?';$p[]=$accion;}if($desde){$w[]='DATE(b.fecha)>=?';$p[]=$desde;}if($hasta){$w[]='DATE(b.fecha)<=?';$p[]=$hasta;}$sql='SELECT b.*,COALESCE(CONCAT(u.nombre," ",u.apellido),"Sistema") usuario_nombre FROM bitacora_mg b LEFT JOIN usuarios u ON u.id_usuario=b.usuario'.($w?' WHERE '.implode(' AND ',$w):'').' ORDER BY b.fecha DESC,b.id DESC LIMIT 300';$s=$pdo->prepare($sql);$s->execute($p);$filas=$s->fetchAll();$tablas=$pdo->query('SELECT DISTINCT tabla FROM bitacora_mg ORDER BY tabla')->fetchAll(PDO::FETCH_COLUMN);$acciones=$pdo->query('SELECT DISTINCT accion FROM bitacora_mg ORDER BY accion')->fetchAll(PDO::FETCH_COLUMN);$tituloPagina='Bitácora de auditoría MG';require __DIR__.'/../views/mg/bitacora.php';
